import * as React from "react"
import { graphql } from "gatsby"
import Layout from "../components/layout"
import Seo from "../components/seo"

const MemoPage = ({ data }) => {
  const posts = data.allMarkdownRemark.nodes

  return (
    <Layout>
      <div className="bg-surface dark:bg-surface shadow-elevation-1 rounded-lg p-6 transition-colors">
        <h1 className="text-headline-large font-bold text-on-surface dark:text-on-surface mb-6">Technical Memos</h1>
        <div className="space-y-8">
          {posts.map((post) => (
            <article key={post.id} className="prose prose-lg dark:prose-invert">
              <div className="text-label-small text-on-surface-variant dark:text-on-surface-variant mb-2">
                {post.frontmatter.date}
              </div>
              <h2 className="text-headline-medium font-bold text-on-surface dark:text-on-surface mb-4">
                {post.frontmatter.title}
              </h2>
              <div
                dangerouslySetInnerHTML={{ __html: post.html }}
                className="text-body-medium text-on-surface dark:text-on-surface"
              />
            </article>
          ))}
        </div>
      </div>
    </Layout>
  )
}

export const query = graphql`
  query {
    allMarkdownRemark(
      filter: { fileAbsolutePath: { regex: "/memo/" } }
      sort: { frontmatter: { date: DESC } }
    ) {
      nodes {
        id
        html
        frontmatter {
          date(formatString: "MMMM DD, YYYY")
          title
        }
      }
    }
  }
`
export const Head = () => <Seo title="Technical Memos" />

export default MemoPage